package httpapi
import("encoding/json";"log/slog";"net/http";"time";"github.com/go-chi/chi/v5";"github.com/go-chi/chi/v5/middleware")
func NewRouter(logger *slog.Logger)http.Handler{r:=chi.NewRouter();r.Use(middleware.RequestID,middleware.RealIP,middleware.Recoverer,middleware.Timeout(20*time.Second));r.Get("/health/live",func(w http.ResponseWriter,_ *http.Request){respond(w,200,map[string]string{"status":"alive"})});r.Get("/health/ready",func(w http.ResponseWriter,_ *http.Request){respond(w,200,map[string]string{"status":"ready"})});r.Get("/v1",func(w http.ResponseWriter,_ *http.Request){respond(w,200,map[string]string{"service":"fintech-transaction-engine","version":"v1"})});r.NotFound(func(w http.ResponseWriter,q *http.Request){respond(w,404,map[string]string{"error":"route not found","request_id":middleware.GetReqID(q.Context())})});return logRequests(logger,r)}
func respond(w http.ResponseWriter,status int,v any){w.Header().Set("Content-Type","application/json; charset=utf-8");w.Header().Set("Cache-Control","no-store");w.WriteHeader(status);_=json.NewEncoder(w).Encode(v)}
func logRequests(l *slog.Logger,next http.Handler)http.Handler{return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){start:=time.Now();next.ServeHTTP(w,r);l.Info("request","method",r.Method,"path",r.URL.Path,"duration_ms",time.Since(start).Milliseconds(),"request_id",middleware.GetReqID(r.Context()))})}
